package dev.myjarvis.core;

import jakarta.servlet.http.Cookie;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

class ScheduleHttpTest {
    MockMvc http;ScheduleService schedules;AuthService auth;AuthService.Session session;Cookie cookie;UUID owner,id,key;
    @BeforeEach void setup(){owner=UUID.randomUUID();id=UUID.randomUUID();key=UUID.fromString("abcdefab-cdef-4abc-8abc-abcdefabcdef");session=new AuthService.Session("synthetic-reminder-session",owner,Instant.now(),1);cookie=new Cookie(WebSecurity.COOKIE,"synthetic-reminder-token");auth=mock(AuthService.class);schedules=mock(ScheduleService.class);when(auth.find("synthetic-reminder-token")).thenReturn(session);when(auth.csrf(session,"synthetic-csrf")).thenReturn(true);http=MockMvcBuilders.standaloneSetup(new ScheduleController(schedules)).setControllerAdvice(new ApiErrors()).addFilters(new WebSecurity(auth,"https://localhost:8443",false)).build();}
    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder write(String path){return post(path).cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","synthetic-csrf").contentType("application/json");}
    @Test void prepareHasNoKeyAndCreatesOnlyPreviewRouteCall() throws Exception{when(schedules.prepare(eq(session),any())).thenReturn(Map.of("status","PREPARED"));var response=http.perform(write("/api/v1/schedule-preparations").content("{\"operation\":\"CREATE\",\"target_id\":null,\"expected_version\":null,\"definition\":{}}")).andReturn().getResponse();assertEquals(200,response.getStatus());assertEquals("no-store",response.getHeader("Cache-Control"));verify(schedules).prepare(eq(session),argThat(b->b.get("operation").asText().equals("CREATE")));verifyNoMoreInteractions(schedules);}
    @Test void confirmUsesServerSessionTargetAndExactIdempotencyKey() throws Exception{when(schedules.confirm(eq(session),eq(key),eq(id),any())).thenReturn(Map.of("status","COMMITTED","schedule_id",UUID.randomUUID(),"version",1,"operation","CREATE"));var response=http.perform(write("/api/v1/schedule-preparations/"+id+"/confirm").header("Idempotency-Key",key.toString()).content("{\"expected_preparation_version\":1,\"payload_hash\":\""+"0".repeat(64)+"\",\"confirm\":true}")).andReturn().getResponse();assertEquals(200,response.getStatus());verify(schedules).confirm(eq(session),eq(key),eq(id),argThat(b->b.size()==3));}
    @Test void authenticationOriginAndCsrfRejectBeforeService() throws Exception{assertEquals(401,http.perform(get("/api/v1/schedules")).andReturn().getResponse().getStatus());for(String path:List.of("/api/v1/schedule-preparations","/api/v1/schedule-preparations/"+id+"/confirm","/api/v1/schedules/"+id+"/disable")){assertEquals(403,http.perform(post(path).cookie(cookie).contentType("application/json").content("{}")).andReturn().getResponse().getStatus());assertEquals(403,http.perform(post(path).cookie(cookie).header("Origin","https://foreign.invalid").header("X-CSRF-Token","synthetic-csrf").contentType("application/json").content("{}")).andReturn().getResponse().getStatus());
        for(String csrf:List.of("","wrong-csrf")){var request=post(path).cookie(cookie).header("Origin","https://localhost:8443").contentType("application/json").content("{}");if(!csrf.isEmpty())request.header("X-CSRF-Token",csrf);var response=http.perform(request).andReturn().getResponse();assertEquals(403,response.getStatus());assertEquals("CSRF_REJECTED",Json.parse(response.getContentAsByteArray()).get("error").get("code").asText());}}
        verifyNoInteractions(schedules);}
    @Test void missingRepeatedAndMalformedKeysAreRejected() throws Exception{for(String path:List.of("/api/v1/schedule-preparations/"+id+"/confirm","/api/v1/schedules/"+id+"/disable")){for(String value:List.of("","1-1-1-1-1",key.toString().toUpperCase(Locale.ROOT))){var request=write(path).content("{}");if(!value.isEmpty())request.header("Idempotency-Key",value);assertEquals(400,http.perform(request).andReturn().getResponse().getStatus());}assertEquals(400,http.perform(write(path).header("Idempotency-Key",key.toString(),key.toString()).content("{}")).andReturn().getResponse().getStatus());}verifyNoInteractions(schedules);}
    @Test void unknownRepeatedAndUnsafeQueryParametersReject() throws Exception{for(String suffix:List.of("?limit=0","?limit=51","?limit=01","?limit=+1","?limit=1&limit=2","?owner_id="+owner,"?cursor=","?project_id=null","?project_id=")){assertEquals(400,http.perform(get("/api/v1/schedules"+suffix).cookie(cookie)).andReturn().getResponse().getStatus());}assertEquals(400,http.perform(get("/api/v1/schedules/"+id+"?cursor=x").cookie(cookie)).andReturn().getResponse().getStatus());assertEquals(400,http.perform(get("/api/v1/schedules/"+id+"/occurrences?project_id="+owner).cookie(cookie)).andReturn().getResponse().getStatus());verifyNoInteractions(schedules);}
    @Test void receiptGetCannotReplayAWrite() throws Exception{Map<String,Object> receipt=new LinkedHashMap<>();receipt.put("status","NOT_OBSERVED");receipt.put("schedule_id",null);receipt.put("version",null);receipt.put("operation",null);when(schedules.reconcile(session,key)).thenReturn(receipt);assertEquals(200,http.perform(get("/api/v1/schedule-mutations/"+key).cookie(cookie)).andReturn().getResponse().getStatus());verify(schedules).reconcile(session,key);verifyNoMoreInteractions(schedules);}
    @Test void conflictReturnsOnlyCurrentVersionMetadata() throws Exception{when(schedules.disable(eq(session),eq(key),eq(id),any())).thenThrow(new ScheduleService.ScheduleConflict(4));var response=http.perform(write("/api/v1/schedules/"+id+"/disable").header("Idempotency-Key",key.toString()).content("{\"expected_version\":1}")).andReturn().getResponse();assertEquals(409,response.getStatus());var error=Json.parse(response.getContentAsByteArray()).get("error");assertEquals("PRECONDITION_CHANGED",error.get("code").asText());assertEquals(1,error.get("details").size());assertEquals(4,error.get("details").get("current_version").asLong());}
    @Test void duplicateKeysAndNonIntegerJsonNeverReachService() throws Exception{for(String json:List.of("{\"operation\":\"CREATE\",\"operation\":\"REPLACE\"}","{\"expected_version\":1.0}","{\"expected_version\":9007199254740992}")){assertEquals(400,http.perform(write("/api/v1/schedule-preparations").content(json)).andReturn().getResponse().getStatus());}verifyNoInteractions(schedules);}
}
